/**
 * Auth configuration — generated by `npx auth-client init`.
 *
 * This file belongs to YOUR project. The base URL comes from the environment
 * so the same build can point at local, staging and production.
 */
import { createAuthClient } from '@7edge/auth-client'

/**
 * Vite exposes env vars prefixed with VITE_ on `import.meta.env`.
 *  - Create React App:  process.env.REACT_APP_API_BASE_URL
 *  - Next.js:           process.env.NEXT_PUBLIC_API_BASE_URL
 */
export const API_BASE_URL =
  import.meta.env.VITE_API_BASE_URL || 'http://localhost:3000/api'

/**
 * Until the backend is live, leave VITE_AUTH_USE_MOCK=true in .env — the
 * library runs a full in-memory backend with no network. Flip it to false
 * (or remove it) once VITE_API_BASE_URL points at the real API; no other
 * code changes are needed.
 */
export const USE_MOCK = import.meta.env.VITE_AUTH_USE_MOCK !== 'false'

export const authConfig = {
  baseURL: API_BASE_URL,
  useMock: USE_MOCK,

  // Renew the token this many seconds before it expires.
  expirySkewSeconds: 30,

  // Keep every open tab in sync on refresh and logout.
  crossTab: true,

  // Fired when a refresh fails and the session cannot be recovered.
  onForceLogout: () => {
    // e.g. redirect to your login route:
    // window.location.href = '/login'
  },
}

/**
 * A single client for the whole app. Import this anywhere — including
 * non-React code such as an API layer that needs `getValidToken()`.
 */
export const authClient = createAuthClient(authConfig)
